import{_ as o,c as t,o as a,aj as s}from"./chunks/framework.Id7s26SP.js";const b=JSON.parse('{"title":"Interface: AgentSessionInfo","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/AgentSessionInfo.md","filePath":"reference/js-bao-wss-client/api/interfaces/AgentSessionInfo.md"}'),n={name:"reference/js-bao-wss-client/api/interfaces/AgentSessionInfo.md"};function r(i,e,c,d,l,h){return a(),t("div",null,[...e[0]||(e[0]=[s('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / AgentSessionInfo</p><h1 id="interface-agentsessioninfo" tabindex="-1">Interface: AgentSessionInfo <a class="header-anchor" href="#interface-agentsessioninfo" aria-label="Permalink to “Interface: AgentSessionInfo”">​</a></h1><p>One agent session, as <code>client.agents.sessions.get()</code> answers it: who it belongs to, which agent it runs, its members, its status, and the document that holds its conversation. The conversation itself is read by opening <code>documentId</code> with the document client (or <code>open()</code>), never through this call.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="agentkey" tabindex="-1">agentKey <a class="header-anchor" href="#agentkey" aria-label="Permalink to “agentKey”">​</a></h3><blockquote><p><strong>agentKey</strong>: <code>string</code></p></blockquote><p>The agent prompt the session is bound to.</p><hr><h3 id="createdat" tabindex="-1">createdAt <a class="header-anchor" href="#createdat" aria-label="Permalink to “createdAt”">​</a></h3><blockquote><p><strong>createdAt</strong>: <code>string</code></p></blockquote><p>ISO-8601.</p><hr><h3 id="documentid" tabindex="-1">documentId <a class="header-anchor" href="#documentid" aria-label="Permalink to “documentId”">​</a></h3><blockquote><p><strong>documentId</strong>: <code>string</code></p></blockquote><p>The session&#39;s conversation document.</p><hr><h3 id="hasunread" tabindex="-1">hasUnread <a class="header-anchor" href="#hasunread" aria-label="Permalink to “hasUnread”">​</a></h3><blockquote><p><strong>hasUnread</strong>: <code>boolean</code></p></blockquote><p>Whether you have activity in this session you have not marked read (<code>markRead()</code>): an agent&#39;s answer or pause, a turn&#39;s end, or another member&#39;s message or event. Always false for an app owner or admin who is not in the session.</p><hr><h3 id="lastactivityat" tabindex="-1">lastActivityAt <a class="header-anchor" href="#lastactivityat" aria-label="Permalink to “lastActivityAt”">​</a></h3><blockquote><p><strong>lastActivityAt</strong>: <code>string</code> | <code>null</code></p></blockquote><p>ISO-8601; null when the session&#39;s listing entry is missing.</p><hr><h3 id="lastreadat" tabindex="-1">lastReadAt <a class="header-anchor" href="#lastreadat" aria-label="Permalink to “lastReadAt”">​</a></h3><blockquote><p><strong>lastReadAt</strong>: <code>string</code> | <code>null</code></p></blockquote><p>When you last marked the session read (ISO-8601), or null.</p><hr><h3 id="members" tabindex="-1">members <a class="header-anchor" href="#members" aria-label="Permalink to “members”">​</a></h3><blockquote><p><strong>members</strong>: <a href="./AgentSessionMembers.html"><code>AgentSessionMembers</code></a></p></blockquote><hr><h3 id="object" tabindex="-1">object? <a class="header-anchor" href="#object" aria-label="Permalink to “object?”">​</a></h3><blockquote><p><code>optional</code> <strong>object?</strong>: <a href="./AgentSessionObjectState.html"><code>AgentSessionObjectState</code></a></p></blockquote><p>For app owners and admins only: what only the session object knows.</p><hr><h3 id="owneruserid" tabindex="-1">ownerUserId <a class="header-anchor" href="#owneruserid" aria-label="Permalink to “ownerUserId”">​</a></h3><blockquote><p><strong>ownerUserId</strong>: <code>string</code></p></blockquote><hr><h3 id="role" tabindex="-1">role <a class="header-anchor" href="#role" aria-label="Permalink to “role”">​</a></h3><blockquote><p><strong>role</strong>: <code>&quot;owner&quot;</code> | <code>&quot;admin&quot;</code> | <code>&quot;viewer&quot;</code> | <code>&quot;participant&quot;</code></p></blockquote><p>The caller&#39;s standing: their role in the session, or <code>admin</code> when they reached it as an app owner or admin without being in it.</p><hr><h3 id="scope" tabindex="-1">scope <a class="header-anchor" href="#scope" aria-label="Permalink to “scope”">​</a></h3><blockquote><p><strong>scope</strong>: <code>string</code> | <code>null</code></p></blockquote><hr><h3 id="sessionid" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid" aria-label="Permalink to “sessionId”">​</a></h3><blockquote><p><strong>sessionId</strong>: <code>string</code></p></blockquote><hr><h3 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to “status”">​</a></h3><blockquote><p><strong>status</strong>: <a href="./../type-aliases/AgentSessionStatus.html"><code>AgentSessionStatus</code></a></p></blockquote><p>Decided from the session object, never the session row.</p><hr><h3 id="title" tabindex="-1">title <a class="header-anchor" href="#title" aria-label="Permalink to “title”">​</a></h3><blockquote><p><strong>title</strong>: <code>string</code> | <code>null</code></p></blockquote><hr><h3 id="turn" tabindex="-1">turn <a class="header-anchor" href="#turn" aria-label="Permalink to “turn”">​</a></h3><blockquote><p><strong>turn</strong>: <a href="./AgentSessionTurnSummary.html"><code>AgentSessionTurnSummary</code></a> | <code>null</code></p></blockquote><p>The active turn, or null when none runs.</p>',60)])])}const u=o(n,[["render",r]]);export{b as __pageData,u as default};
